// src/features/Sales/pages/SalesManagement.jsx
import React, { useState } from 'react';
import {
  Container,
  Typography,
  Divider,
  Box,
  Tabs,
  Tab,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  TextField,
  InputAdornment
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import SearchIcon from '@mui/icons-material/Search';

// Función local para formatear moneda
const formatCurrency = (value) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(value || 0);
};

// Función local para formatear fecha
const formatDate = (dateString) => {
  const date = new Date(dateString);
  return date.toLocaleDateString('es-MX', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

const SalesManagement = () => {
  const [tabValue, setTabValue] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchTerm, setSearchTerm] = useState('');

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSearchChange = (event) => {
    setSearchTerm(event.target.value);
  };

  // Datos de ejemplo para ventas
  const sales = [
    { id: 1, date: '2023-05-20', customer: 'Cliente A', invoice: 'INV-001', total: 1500, status: 'Completada' },
    { id: 2, date: '2023-05-19', customer: 'Cliente B', invoice: 'INV-002', total: 2300, status: 'Pendiente' },
    { id: 3, date: '2023-05-18', customer: 'Cliente C', invoice: 'INV-003', total: 980, status: 'Completada' },
    { id: 4, date: '2023-05-17', customer: 'Cliente D', invoice: 'INV-004', total: 3200, status: 'Cancelada' },
    { id: 5, date: '2023-05-16', customer: 'Cliente E', invoice: 'INV-005', total: 1750, status: 'Completada' }
  ];

  // Datos de ejemplo para clientes
  const customers = [
    { id: 1, name: 'Cliente A', email: 'clientea@example.com', phone: '555-1234', totalPurchases: 5000 },
    { id: 2, name: 'Cliente B', email: 'clienteb@example.com', phone: '555-5678', totalPurchases: 3500 },
    { id: 3, name: 'Cliente C', email: 'clientec@example.com', phone: '555-9012', totalPurchases: 2800 },
    { id: 4, name: 'Cliente D', email: 'cliented@example.com', phone: '555-3456', totalPurchases: 4200 },
    { id: 5, name: 'Cliente E', email: 'clientee@example.com', phone: '555-7890', totalPurchases: 1900 }
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case 'Completada':
        return 'success';
      case 'Pendiente':
        return 'warning';
      case 'Cancelada':
        return 'error';
      default:
        return 'default';
    }
  };

  // Componente de Tabla de Ventas
  const SalesTable = () => {
    const filteredSales = sales.filter(sale => 
      sale.customer.toLowerCase().includes(searchTerm.toLowerCase()) ||
      sale.invoice.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
      <Paper sx={{ p: 2, width: '100%' }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6">Registro de Ventas</Typography>
          
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
          >
            Nueva Venta
          </Button>
        </Box>
        
        <TextField
          fullWidth
          margin="normal"
          placeholder="Buscar por cliente o factura..."
          value={searchTerm}
          onChange={handleSearchChange}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
          sx={{ mb: 2 }}
        />
        
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>ID</TableCell>
                <TableCell>Fecha</TableCell>
                <TableCell>Cliente</TableCell>
                <TableCell>Factura</TableCell>
                <TableCell align="right">Total</TableCell>
                <TableCell align="center">Estado</TableCell>
                <TableCell align="right">Acciones</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredSales.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((sale) => (
                <TableRow key={sale.id}>
                  <TableCell>{sale.id}</TableCell>
                  <TableCell>{formatDate(sale.date)}</TableCell>
                  <TableCell>{sale.customer}</TableCell>
                  <TableCell>{sale.invoice}</TableCell>
                  <TableCell align="right">{formatCurrency(sale.total)}</TableCell>
                  <TableCell align="center">
                    <Chip 
                      label={sale.status}
                      color={getStatusColor(sale.status)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell align="right">
                    <Button size="small" color="primary">
                      Ver
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {filteredSales.length === 0 && (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    No se encontraron ventas
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        
        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={filteredSales.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </Paper>
    );
  };

  // Componente de Tabla de Clientes
  const CustomerTable = () => {
    const filteredCustomers = customers.filter(customer => 
      customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      customer.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
      <Paper sx={{ p: 2, width: '100%' }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6">Clientes</Typography>
          
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
          >
            Nuevo Cliente
          </Button>
        </Box>
        
        <TextField
          fullWidth
          margin="normal"
          placeholder="Buscar por nombre o email..."
          value={searchTerm}
          onChange={handleSearchChange}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
          sx={{ mb: 2 }}
        />
        
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>ID</TableCell>
                <TableCell>Nombre</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Teléfono</TableCell>
                <TableCell align="right">Compras Totales</TableCell>
                <TableCell align="right">Acciones</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredCustomers.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((customer) => (
                <TableRow key={customer.id}>
                  <TableCell>{customer.id}</TableCell>
                  <TableCell>{customer.name}</TableCell>
                  <TableCell>{customer.email}</TableCell>
                  <TableCell>{customer.phone}</TableCell>
                  <TableCell align="right">{formatCurrency(customer.totalPurchases)}</TableCell>
                  <TableCell align="right">
                    <Button size="small" color="primary">
                      Ver
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {filteredCustomers.length === 0 && (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No se encontraron clientes
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        
        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={filteredCustomers.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </Paper>
    );
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Control de Ventas
      </Typography>
      <Divider sx={{ mb: 4 }} />

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tabValue} onChange={handleTabChange} aria-label="sales tabs">
          <Tab label="Ventas" />
          <Tab label="Clientes" />
          <Tab label="Facturas" />
        </Tabs>
      </Box>

      <Box sx={{ mt: 2 }}>
        {tabValue === 0 && <SalesTable />}
        {tabValue === 1 && <CustomerTable />}
        {tabValue === 2 && (
          <Paper sx={{ p: 2, width: '100%', textAlign: 'center' }}>
            <Typography variant="h6" color="text.secondary">
              Módulo de Facturas en Desarrollo
            </Typography>
          </Paper>
        )}
      </Box>
    </Container>
  );
};

export default SalesManagement;